    /** The mounting step of a right click: an empty hand mounts (sneaking passes, as vanilla dismounts); a saddle the mob can take passes to vanilla's item use, which equips it; the first seat is the owner's; a full mob or a baby passes on; on_mount fires once per mount by right click (not for /ride). Null passes on. */
    private InteractionResult ridingInteract(Player player, InteractionHand hand) {
        if (player.isSecondaryUseActive()) {
            return null;
        }
        ItemStack stack = player.getItemInHand(hand);
        if (!stack.isEmpty()) {
            boolean saddle = !isSaddled() && isEquippableInSlot(stack, EquipmentSlot.SADDLE);
            return saddle ? InteractionResult.PASS : null;
        }
        if (isBaby() || hasPassenger(player) || getPassengers().size() >= 2) {
            return null;
        }
        if (getPassengers().isEmpty() && !allowedToSteer(player)) {
            return null;
        }
        if (level() instanceof ServerLevel level) {
            if (!player.startRiding(this)) {
                return null;
            }
            event_gs_mounted(level, blockPosition(), position(), player, this, 1);
        }
        return InteractionResult.SUCCESS;
    }

    /** The first passenger steers when it is a player and the mob is saddled and it is the owner; another player passenger only sits. */
