    @Override
    public void handleStopJump() {}

    /** saddle_bone: the model bone hidden while the saddle slot is empty; read by the GeckoLib model. */
    public String hiddenBone() {
        return isSaddled() ? null : "saddle";
    }

    /** msm_main loops sit, swim in that order of precedence, then walk while moving and idle otherwise; the other controllers play animations on request. */
    @Override
    public void registerControllers(AnimatableManager.ControllerRegistrar controllers) {
        RawAnimation idle = RawAnimation.begin().thenLoop("idle");
        RawAnimation walk = RawAnimation.begin().thenLoop("walk");
        RawAnimation sit = RawAnimation.begin().thenLoop("sit");
        RawAnimation swim = RawAnimation.begin().thenLoop("swim");
        AnimationController<GsPonyEntity> main = new AnimationController<>("msm_main", 0, test -> {
            RawAnimation loop;
            if (isInSittingPose()) {
                loop = sit;
            } else if (test.isMoving() && isInWater()) {
                loop = swim;
            } else {
                loop = test.isMoving() && walk != null ? walk : idle;
            }
            return loop == null ? PlayState.STOP : test.setAndContinue(loop);
        });
        controllers.add(main);
        AnimationController<GsPonyEntity> triggered = new AnimationController<>("msm_triggered", 0, test -> PlayState.STOP);
        triggered.triggerableAnim("idle", RawAnimation.begin().thenPlay("idle"));
        triggered.triggerableAnim("walk", RawAnimation.begin().thenPlay("walk"));
        triggered.triggerableAnim("sit", RawAnimation.begin().thenPlay("sit"));
        controllers.add(triggered);
    }

    @Override
    public AnimatableInstanceCache getAnimatableInstanceCache() {
        return cache;
    }

    /** Event {@code msm_test:gs_born}. */
    private void event_gs_born(ServerLevel level, BlockPos base, Vec3 origin, Player player, Entity entity, int depth) {
        if (Actions.tooDeep(OWNER, "msm_test:gs_born", depth)) {
            return;
        }
        triggerAnim("msm_triggered", "sit");
    }

    /** Event {@code msm_test:gs_mounted}. */
    private void event_gs_mounted(ServerLevel level, BlockPos base, Vec3 origin, Player player, Entity entity, int depth) {
        if (Actions.tooDeep(OWNER, "msm_test:gs_mounted", depth)) {
            return;
        }
        Actions.spawnParticle(OWNER, level, origin, "minecraft:heart", 1, 0.0f, 0.0f);
    }

    /** Event {@code msm_test:gs_tamed}. */
    private void event_gs_tamed(ServerLevel level, BlockPos base, Vec3 origin, Player player, Entity entity, int depth) {
        if (Actions.tooDeep(OWNER, "msm_test:gs_tamed", depth)) {
            return;
        }
        Actions.playSound(OWNER, level, origin, entity, "minecraft:entity.experience_orb.pickup", 0.1f, 1.0f);
    }
